CREATE COLUMN TABLE "TEST_AP"."SRA2" ("ActionCode" INTEGER CS_INT NOT NULL , "Date" LONGDATE CS_LONGDATE NOT NULL , "Time" INTEGER CS_INT NOT NULL , "Status" NVARCHAR(1) DEFAULT '0', "ReturnCode" INTEGER CS_INT, "ReturnStr" NVARCHAR(250), "ResDag" BLOB MEMORY THRESHOLD 1000, "ResPdf" BLOB MEMORY THRESHOLD 1000, "ResHtml" BLOB MEMORY THRESHOLD 1000, "ResXml" BLOB MEMORY THRESHOLD 1000, "Results" NVARCHAR(10) DEFAULT 'NNNN', "ResLog" BLOB MEMORY THRESHOLD 1000, "ErrScreen" BLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("ActionCode", "Date", "Time")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "SRA2_ACTIONCODE" ON "TEST_AP"."SRA2" ( "ActionCode" ASC )